<style lang="scss" src="./nav-bar.scss"></style>
<style lang="scss" src="./nav-bar-gms.scss"></style>

<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import { has } from "../../util/has";
import Logo from "../logo/logo";
import { LogoAlign } from "../logo/logo.constants";
import { NavBarMode, NavBarModeValues } from "./nav-bar.constants";
import Icon from "../icon/icon";
import { IconShape } from "../icon/icon.constants";

const modeToClass = {
  [NavBarMode.DEFAULT]: "",
  [NavBarMode.GMS]: "NavBar_GMS",
};

/**
 * Header bar that appears at the top of the page
 */
@Component({
  components: { Logo, Icon },
})
export default class NavBar extends Vue {
  /** The logo to pass to the navbar */
  @Prop({ type: String, default: "" }) logo;
  /** True if a shadow border divider should be present */
  @Prop({ type: Boolean, default: false }) shadow;
  /** Rendering mode of the NavBar */
  @Prop({
    type: String,
    default: NavBarMode.DEFAULT,
    validator: has(NavBarModeValues),
  })
  mode;
  /** Tabs to include in the navbar */
  @Prop({
    type: Array,
    default: () => [],
  })
  tabs;
  /**  */
  @Prop({
    type: [Number, String],
    default: "",
  })
  defaultValue;
  @Prop({
    type: Boolean,
    default: false,
  })
  hasNotifications;

  currentTab = { label: void 0, value: 0 };

  NavBarMode = NavBarMode;
  LogoAlign = LogoAlign;

  get IconShape() {
    return IconShape;
  }

  get modeClass() {
    return modeToClass[this.mode];
  }

  get currentValue() {
    return this.currentTab.value;
  }

  get logoStyle() {
    return { backgroundImage: `url(${this.logo})` };
  }

  get notificationShape() {
    return this.hasNotifications ? IconShape.BELL_ALERT : IconShape.BELL;
  }

  handleSelect(tab) {
    this.currentTab = tab;

    /**
     * This event is emitted when the user selects a new tab to navigate to.
     * This provides the tab data selected.
     *
     * @event change
     */
    this.$emit("change", this.currentTab, this.currentTab.value);
  }
}
</script>

<template>
  <div :class="['NavBar', { 'NavBar--Shadow': this.shadow }, modeClass]">
    <div class="NavBar__Container">
      <div class="NavBar__LeftContainer NavBar__Division">
        <Logo
          v-if="mode === NavBarMode.GMS"
          :class="'NavBar__Logo'"
          :source="this.logo"
          :maxWidth="200"
          :maxHeight="52"
          :align="LogoAlign.LEFT_CENTER"
          @click.native="$emit('logoClick')"
        />
        <Logo
          v-else
          :class="'NavBar__Logo'"
          :source="this.logo"
          :maxWidth="200"
          :maxHeight="48"
          :align="LogoAlign.LEFT_CENTER"
          @click.native="$emit('logoClick')"
        />
      </div>
      <div
        v-if="mode === NavBarMode.GMS"
        class="NavBar__MiddleContainer NavBar__Division"
      >
        <div
          v-for="(tab, index) in tabs"
          :class="[
            'NavBar__Tab',
            currentValue === tab.value
              ? 'NavBar--selected'
              : 'NavBar--unselected',
          ]"
          :key="index"
          @click="handleSelect(tab)"
        >
          {{ tab.label }}
          <div v-if="currentValue === tab.value" class="NavBar__Underline" />
        </div>
      </div>
      <div class="NavBar__RightContainer NavBar__Division">
        <slot />
        <div v-if="mode === NavBarMode.GMS" class="NavBar__Notifications">
          <div v-if="hasNotifications" class="NavBar__Alert" :key="0">
            <Icon
              :shape="IconShape.BELL_ALERT"
              :width="27"
              :color="'#000000'"
            />
          </div>
          <div v-else class="NavBar__NoAlert" :key="1">
            <Icon :shape="IconShape.BELL" :width="24" :color="'#000000'" />
          </div>
        </div>
      </div>
    </div>
  </div>
</template>
